const OWNER_REPO = /^[A-Za-z0-9-]+\/[A-Za-z0-9._-]+$/;

/** GitHub URL for a card's `owner/repo`. Refuses a bare slug rather than guessing an owner. */
export const gh = (repo: string) => {
  if (!OWNER_REPO.test(repo)) {
    throw new Error(`gh() needs an owner/repo, got "${repo}"`);
  }
  return `https://github.com/${repo}`;
};
const vercel = (dir: string) => {
  const name = dir.replace(/^bookchaowalit-/, "").replace(/-frontend$/, "");
  return `https://${name}.bookchaowalit.com`;
};
const sub = (slug: string) => `https://${slug}.bookchaowalit.com`;

