// A card links its source only when it carries a public owner/repo. Private,
// archived-private or missing repositories carry no repo, so no source URL
// reaches the client bundle, JSON-LD or MCP output.
export const allProjects: AppProject[] = projectEntries.map((entry) => ({
  ...entry,
  githubUrl: entry.repo ? gh(entry.repo) : "",
  sourceUnavailable: entry.repo ? undefined : true,
}));

/** The source URL that may be published (UI, JSON-LD, MCP); empty when the source is hidden. */
export function publicSourceUrl(project: Pick<AppProject, "githubUrl" | "sourceUnavailable">): string {
  return project.sourceUnavailable ? "" : project.githubUrl;
}

/** The demo URL that may be published; empty when no working demo of ours exists. */
export function publicDemoUrl(project: Pick<AppProject, "url" | "demoUnavailable">): string {
  return project.demoUnavailable ? "" : project.url;
}

export function getProjectStatusCounts(projects: readonly AppProject[] = allProjects) {
  return projects.reduce(
    (counts, project) => {
      counts[project.status] += 1;
      return counts;
    },
    { live: 0, wip: 0, archived: 0 },
  );
}
